window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["advanced-rag"]={"title":"高级 RAG：让检索成为可诊断、可迭代的证据流程","subtitle":"从查询改写、混合召回、重排、多跳、纠错检索和答案引用理解何时需要升级基础 RAG。","thesis":"高级 RAG 不是堆更多组件，而是针对已测出的失败点改进查询、召回、排序或生成；每个新增环节都应提高<b>证据覆盖、忠实度或任务成功</b>，否则只会增加延迟与不可解释性。","quality":{"contractVersion":2,"examples":[{"section":7,"evidence":{"setup":"签收 35 天的质量问题能退吗","rule":"双路召回 + RRF","steps":"融合扩大证据覆盖，重排和时效规则再把四条缩成","interpretation":"RRF 不是最终裁判"}}],"formulas":[{"id":"advanced-rag-rrf","section":3,"formulaIndex":1,"symbols":[{"name":"RRF","meaning":"倒数排名融合得到的文档分数","evidence":"RRF 分数 RRF(d)"},{"name":"d","meaning":"待融合排名的候选文档","evidence":"文档 d"},{"name":"J","meaning":"参与融合的检索器数量","evidence":"输入 J 路检索器"},{"name":"j","meaning":"检索器编号","evidence":"j 是检索器编号"},{"name":"k","meaning":"降低头部名次差异的平滑常数","evidence":"平滑常数 k"},{"name":"rj","meaning":"文档 d 在第 j 路检索器中的名次","evidence":"候选名次 rj(d)"}]}],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"HyDE","meaning":"生成假设文档以构造语义检索表示的方法","purpose":"在缺少直接关键词时帮助召回潜在相关文档","definitionEvidence":"HyDE 的假设文档只构造搜索表示","purposeEvidence":"改写补搜索表达而不替换用户意图"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"高级 RAG 从可观测中间产物定位检索证据链的失败层。","evidence":"先定位失败层"},"problem":{"answer":"它避免答案错误后未经诊断就盲目增加重排等组件。","evidence":"为什么不能直接加一个重排器"},"inputOutput":{"answer":"输入各层产物，输出首次失败层和可证伪修复假设。","evidence":"输出首次偏离预期的层及可证伪修复假设"},"mechanism":{"answer":"一次只改变一层并在同一数据上复跑比较。","evidence":"一次只改变该层并复跑同一数据"},"interpretation":{"answer":"答案改善而延迟超预算说明复杂链只应路由困难查询。","evidence":"只应把复杂链路路由给困难查询"},"boundary":{"answer":"未定位失败前不能通过堆组件冒充优化。","evidence":"不能直接堆组件"}},{"section":2,"definition":{"answer":"查询改写补充检索表达但必须保留原问题约束。","evidence":"查询改写与扩展"},"problem":{"answer":"它处理用户表达含歧义、省略实体或不适合直接搜索的问题。","evidence":"用户问题为何不一定是最佳搜索词"},"inputOutput":{"answer":"输入原问题实体条件，输出结构化改写或子查询。","evidence":"输出保留约束的结构化改写或多个子查询"},"mechanism":{"answer":"显式记录补充和拆分差异，原问题用于最终验收。","evidence":"原问题仍用于最终验收"},"interpretation":{"answer":"HyDE 假设文档只用于搜索表示而不是证据。","evidence":"HyDE 的假设文档只构造搜索表示"},"boundary":{"answer":"新增实体或丢否定会将检索引向错误前提。","evidence":"必须保留差异与来源"}},{"section":3,"definition":{"answer":"混合召回融合关键词与稠密检索器的候选排名。","evidence":"混合召回与融合"},"problem":{"answer":"它解决精确词与语义改写各自的召回盲区。","evidence":"稠密与关键词为什么互补"},"inputOutput":{"answer":"输入多路名次，输出每个候选的 RRF 分数。","evidence":"输出文档 d 的 RRF 分数 RRF(d)"},"mechanism":{"answer":"各路按名次倒数贡献并相加，避免分数量纲不一。","evidence":"避免直接相加不同量纲分数"},"interpretation":{"answer":"名次靠前贡献更大，但融合分不是事实质量分。","evidence":"名次靠前贡献更大"},"boundary":{"answer":"融合不负责判断来源时效、权限和真实性。","evidence":"不判断时效、权限或真实性"}},{"section":4,"definition":{"answer":"重排与装配把融合候选变成去重、带引用的最终上下文。","evidence":"重排与上下文装配"},"problem":{"answer":"它处理候选重复、相邻块割裂和版本冲突。","evidence":"候选相关后怎样避免重复和冲突"},"inputOutput":{"answer":"输入候选分数和治理信息，输出可引用上下文。","evidence":"输出去重且保留必要冲突与引用的上下文"},"mechanism":{"answer":"精排后合并邻接块并过滤过期无权内容。","evidence":"交叉编码器精排后按来源合并邻接块"},"interpretation":{"answer":"前排相关只说明适合回答，不等于来源可信。","evidence":"前排相关只说明适合回答，不等于可信"},"boundary":{"answer":"权威证据冲突时必须同时保留并解释。","evidence":"必须显式保留和解释"}},{"section":5,"definition":{"answer":"多跳检索根据当前缺失证据逐步生成下一子查询。","evidence":"多跳与自适应检索"},"problem":{"answer":"它解决必须先查 A 才能知道如何查询 B 的问题。","evidence":"需要先查 A 才知道查 B"},"inputOutput":{"answer":"输入问题和槽位缺口，输出子查询实体及槽位状态。","evidence":"输出下一子查询、中间实体及更新后的槽位状态"},"mechanism":{"answer":"每跳验证实体来源并只在填补缺口时继续。","evidence":"每一跳只在填补缺口或解决冲突时继续"},"interpretation":{"answer":"错误实体会沿后续查询传播并形成滚雪球。","evidence":"错误实体会让后续检索滚雪球"},"boundary":{"answer":"必须限制步数资源并设置无进展终止条件。","evidence":"最大步数、预算和无进展终止是必需边界"}},{"section":6,"definition":{"answer":"高级链路评测用组件消融证明每个新增环节的净收益。","evidence":"是否值得升级"},"problem":{"answer":"它回答复杂 RAG 是否真的优于固定的基础 RAG。","evidence":"高级链路如何证明比基础 RAG 好"},"inputOutput":{"answer":"输入基础与单组件变体，输出证据答案延迟成本差异。","evidence":"输出 Recall、NDCG、证据忠实、答案成功、延迟和成本差异"},"mechanism":{"answer":"固定查询集一次增加一个组件并比较端到端结果。","evidence":"通过组件消融确认新增环节"},"interpretation":{"answer":"局部排序变好而答案不变说明瓶颈在后续。","evidence":"瓶颈已在后续"},"boundary":{"answer":"没有稳定端到端净收益的组件应该删除。","evidence":"没有稳定净收益的组件应删除"}},{"section":7,"definition":{"answer":"退款案例依次进行查询分解、双路融合、重排和治理过滤。","evidence":"一次退款查询怎样逐层修复"},"problem":{"answer":"它解释为何不能只通过增大 topK 解决复杂条件问题。","evidence":"为什么需要改写、融合和重排"},"inputOutput":{"answer":"输入两路名次和治理规则，输出共同支撑结论的 A+B。","evidence":"输出可共同支撑结论的 A+B 证据"},"mechanism":{"answer":"RRF 扩候选，重排判资格，时效过滤旧政策。","evidence":"重排识别退款资格，版本过滤删除旧政策"},"interpretation":{"answer":"融合分接近说明 RRF 不能替代细粒度判断。","evidence":"RRF 不是最终裁判"},"boundary":{"answer":"回答只能引用真实取回且通过治理的材料。","evidence":"只能引用真实取回、通过治理检查的材料"}},{"section":8,"definition":{"answer":"纠错循环围绕明确缺失证据槽位决定继续或停止。","evidence":"纠错与多跳何时应该停止"},"problem":{"answer":"它防止证据不足演化成无限查询改写循环。","evidence":"怎样避免把一次缺证变成无休止循环"},"inputOutput":{"answer":"输入槽位证据和预算，输出继续、解冲突或停止。","evidence":"输出继续检索、解决冲突或透明停止"},"mechanism":{"answer":"仅在填缺口、升来源或解冲突时记录进展。","evidence":"只有填补缺口、提升来源等级或解决版本冲突才算进展"},"interpretation":{"answer":"连续两轮无新槽位说明继续搜索没有取得进展。","evidence":"连续两轮无新槽位就停止"},"boundary":{"answer":"假设文本和代理自写内容不可升级为回答证据。","evidence":"不能升级为回答证据"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>诊断 RAG 分层失败；设计混合与多查询；理解 HyDE/纠错检索；控制多跳与循环。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先定位失败层<span class=\"dd-badge intuition\">诊断</span></h2><p class=\"dd-lead\">答案错了，为什么不能直接加一个重排器？</p><p>可能是解析、切分、查询、召回、重排、上下文利用或生成错误。保存每层产物并用证据标注定位瓶颈，避免组件盲堆。</p><p>可把每次失败写成可证伪假设：“若把质量例外加入候选，答案会正确”“若过滤旧版本，引用冲突会消失”。随后只改变这一层并复跑同一查询集。若候选覆盖上升而答案不变，瓶颈已转移到装配或生成；若答案上升但延迟超预算，则只把复杂链路路由给困难查询。分层实验比同时启用多查询、HyDE、重排和 Agent 更能解释收益来自哪里，也保留安全回退路径。</p><p>分层诊断输入查询、解析块、召回候选、重排结果、最终上下文和回答，输出首次偏离预期的层及可证伪修复假设。一次只改变该层并复跑同一数据，才能解释收益来源；答案变好但延迟超预算时只应把复杂链路路由给困难查询。未定位失败前不能直接堆组件。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>查询改写与扩展<span class=\"dd-badge eng\">查询</span></h2><p class=\"dd-lead\">用户问题为何不一定是最佳搜索词？</p><p>可消歧、补实体、生成多查询或假设文档 HyDE。扩展提高召回也可能引入错误假设，原问题与改写都应保留并可审计。</p><p>改写器应输出结构化差异：补了哪个实体、拆了哪些子问题、保留了哪些日期和否定条件。若“不能退吗”被改成“退款流程”，检索虽然主题相似，却已经丢掉资格判断。最终生成必须用原问题验收，改写只服务于寻找证据。</p><p>查询改写输入原问题、实体、日期、否定和歧义，输出保留约束的结构化改写或多个子查询。改写补搜索表达而不替换用户意图，原问题仍用于最终验收；HyDE 的假设文档只构造搜索表示。新增实体或丢失否定会把检索带向错误前提，必须保留差异与来源。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>混合召回与融合<span class=\"dd-badge math\">召回</span></h2><p class=\"dd-lead\">稠密与关键词为什么互补？</p><p>关键词擅长精确名字和数字，稠密向量擅长语义改写。可用 RRF 按排名融合，减少分数尺度不一致；权重按查询类型验证，并保留各路原始名次用于回归诊断。</p><p>混合融合输入 J 路检索器各自的候选名次 rj(d) 和平滑常数 k，输出文档 d 的 RRF 分数 RRF(d)。j 是检索器编号；每一路按 1/(k+rj(d)) 贡献，名次靠前贡献更大，避免直接相加不同量纲分数；融合只扩大和排序候选，不判断时效、权限或真实性。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"倒数排名融合分数\"><mi>RRF</mi><mo>(</mo><mi>d</mi><mo>)</mo><mo>=</mo><munderover><mo>∑</mo><mrow><mi>j</mi><mo>=</mo><mn>1</mn></mrow><mi>J</mi></munderover><mfrac><mn>1</mn><mrow><mi>k</mi><mo>+</mo><mi>rj</mi><mo>(</mo><mi>d</mi><mo>)</mo></mrow></mfrac></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>重排与上下文装配<span class=\"dd-badge eng\">排序</span></h2><p class=\"dd-lead\">候选相关后怎样避免重复和冲突？</p><p>交叉编码器精排，按来源去重并扩展相邻块；同时保留不同观点与时间版本。关键证据放在任务附近并带引用。</p><p>上下文装配输入融合候选、重排分、来源、邻接、版本和权限，输出去重且保留必要冲突与引用的上下文。交叉编码器精排后按来源合并邻接块，并过滤过期和无权内容；前排相关只说明适合回答，不等于可信。相互冲突的权威证据必须显式保留和解释。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>多跳与自适应检索<span class=\"dd-badge intuition\">Agentic RAG</span></h2><p class=\"dd-lead\">一个问题需要先查 A 才知道查 B 时怎么办？</p><p>将问题拆成子问题，逐步检索并记录中间实体；若证据不足或冲突，触发补检索。必须限制步数并验证每跳，防止错误查询滚雪球。</p><p>多跳检索输入问题、已知证据槽位和当前缺口，输出下一子查询、中间实体及更新后的槽位状态。每一跳只在填补缺口或解决冲突时继续，并验证实体和来源；错误实体会让后续检索滚雪球。最大步数、预算和无进展终止是必需边界。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>是否值得升级<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">高级链路如何证明比基础 RAG 好？</p><p>用固定查询集做组件消融，分别报告 Recall、NDCG、证据忠实、答案成功、延迟和成本。若重排提升排序却不提升答案，应检查上下文利用而非继续加组件。</p><div class=\"dd-note warn\"><b>更多检索不等于更多真相。</b>　重复、过期和低可信来源会放大噪声。</div><p>升级评测输入固定查询集、基础 RAG 与单组件变体，输出 Recall、NDCG、证据忠实、答案成功、延迟和成本差异。通过组件消融确认新增环节是否改善端到端任务，而非只改善自己的局部指标；排序提高但答案不变说明瓶颈已在后续。没有稳定净收益的组件应删除。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>一次退款查询怎样逐层修复<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">“签收 35 天的质量问题能退吗”为什么需要改写、融合和重排，而不是只把 top-k 调大？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 220\" role=\"img\" aria-label=\"高级 RAG 从原问题经查询分解、双路召回、融合重排到证据回答的流程\"><defs><marker id=\"ar1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"15\" y=\"55\" width=\"115\" height=\"78\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"72\" y=\"78\" text-anchor=\"middle\" class=\"svg-t\">原问题</text><text x=\"72\" y=\"99\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">35 天 + 质量问题</text><text x=\"72\" y=\"117\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">能否退款？</text><path d=\"M130,94 L174,94\" stroke=\"#6b7484\" marker-end=\"url(#ar1)\"/><rect x=\"176\" y=\"39\" width=\"128\" height=\"110\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"240\" y=\"64\" text-anchor=\"middle\" class=\"svg-t\">查询分解</text><text x=\"240\" y=\"87\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">一般期限</text><text x=\"240\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">质量例外</text><text x=\"240\" y=\"123\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">政策版本</text><path d=\"M304,94 L348,94\" stroke=\"#6b7484\" marker-end=\"url(#ar1)\"/><rect x=\"350\" y=\"28\" width=\"142\" height=\"132\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"421\" y=\"53\" text-anchor=\"middle\" class=\"svg-t\">双路召回 + RRF</text><text x=\"421\" y=\"77\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">BM25：编号/30 天</text><text x=\"421\" y=\"96\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">向量：质量例外</text><text x=\"421\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">去重 · 权限 · 时效</text><text x=\"421\" y=\"137\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">交叉编码重排</text><path d=\"M492,94 L536,94\" stroke=\"#6b7484\" marker-end=\"url(#ar1)\"/><rect x=\"538\" y=\"44\" width=\"127\" height=\"100\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"601\" y=\"68\" text-anchor=\"middle\" class=\"svg-t\">逐断言回答</text><text x=\"601\" y=\"91\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">一般规则 + 例外</text><text x=\"601\" y=\"110\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">订单事实 + 引用</text><text x=\"601\" y=\"129\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">不足则拒答/补查</text><path d=\"M602,145 C590,202 242,205 240,150\" fill=\"none\" stroke=\"#6b7484\" marker-end=\"url(#ar1)\"/><text x=\"422\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">引用不支撑结论时，把失败归因回查询、召回或装配层</text></svg><figcaption>图 1　高级 RAG 的价值是让每一层产物可检查并能回流修复；它不是一条只能向前的组件流水线。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>BM25 名次</th><th>向量名次</th><th>RRF 分数（k=60）</th><th>重排判断</th></tr></thead><tbody><tr><td>A：30 天一般规则</td><td>1</td><td>4</td><td>1/61+1/64=0.0320</td><td>必要但不充分</td></tr><tr><td>B：质量问题例外</td><td>5</td><td>1</td><td>1/65+1/61=0.0318</td><td>回答核心</td></tr><tr><td>C：到账时间</td><td>2</td><td>3</td><td>1/62+1/63=0.0320</td><td>主题近但不回答资格</td></tr><tr><td>D：旧版政策</td><td>3</td><td>2</td><td>1/63+1/62=0.0320</td><td>因版本过期剔除</td></tr></tbody></table></div><p>RRF 只利用名次，避免直接相加不可比的 BM25 与余弦分数；但表中 A、C、D 得分几乎相同，证明融合不是最终裁判。重排必须围绕“退款资格”判断细粒度相关性，时效过滤还要把看似最相关的旧政策移除。最终上下文保留 A+B 和订单日期，才足以推出：一般期限已过，但质量例外仍可能适用。</p><div class=\"dd-note key\"><b>可复算结论：</b>只用单路 top-2 时，BM25 得到 A+C，缺少例外；向量得到 B+D，缺少当前一般规则。融合扩大证据覆盖，重排和时效规则再把四条缩成可共同支撑结论的 A+B。</div><p>退款案例输入原问题、BM25 与向量名次、RRF、重排、时效和权限规则，输出可共同支撑结论的 A+B 证据。A 和 C 的融合分几乎相同说明 RRF 不是最终裁判；重排识别退款资格，版本过滤删除旧政策。最终回答只能引用真实取回、通过治理检查的材料。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>纠错与多跳何时应该停止<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">系统发现证据不足后继续搜索，怎样避免把一次缺证变成无休止循环？</p><p>每轮检索都要声明尚缺的证据槽位，例如“订单事实已知、一般规则已知、质量例外未知”，而不是笼统要求“再找更多”。新一轮只有在填补槽位、解决版本冲突或提高来源等级时才算取得进展。应设置最大跳数、最大查询数、token/延迟预算和无进展终止条件；达到边界后输出已知、未知和需要人工确认的事项。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>观察</th><th>正确动作</th><th>不应做的事</th></tr></thead><tbody><tr><td>正确文档从未进入候选</td><td>修查询、切块或召回通道</td><td>只换生成提示</td></tr><tr><td>候选里有证据但排得靠后</td><td>重排、去重与版本过滤</td><td>无限扩大上下文</td></tr><tr><td>证据互相冲突</td><td>核对日期、权限和权威来源</td><td>按多数片段投票</td></tr><tr><td>连续两轮没有新证据槽位</td><td>停止并透明报告不足</td><td>让 Agent 自由改写查询循环</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>失败边界：</b>HyDE 生成的“假设文档”只用于构造搜索表示，不是证据。若它虚构了产品名或条款，后续召回可能围绕错误前提滚雪球；回答只能引用真实取回且通过版本、权限检查的材料。</div><p>纠错循环输入已知槽位、缺失槽位、新证据、跳数和资源预算，输出继续检索、解决冲突或透明停止。只有填补缺口、提升来源等级或解决版本冲突才算进展；连续两轮无新槽位就停止。HyDE 假设文本和 Agent 自写内容不能升级为回答证据。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">“高级”不意味着所有查询都必须经过更多模型和更多轮。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>组件越多，答案越可靠</td><td>只有针对已定位失败且经消融证明有端到端收益的组件才值得保留</td></tr><tr><td>融合分数最高就是最好证据</td><td>融合解决跨检索器排序，不能代替时效、权限、真实性和任务相关性判断</td></tr><tr><td>多跳会自动完成复杂推理</td><td>每一跳都会传播实体解析和检索错误，必须记录证据槽位并设置终止条件</td></tr><tr><td>查询改写可以替换原问题</td><td>改写可能改变约束；原问题必须保留，用于最终答案验收</td></tr><tr><td>离线检索指标升高就完成优化</td><td>还需验证逐断言证据覆盖、引用忠实、答案成功、延迟与成本</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>RAG、检索、切块、嵌入、向量数据库</td></tr><tr><td><b>本页核心</b></td><td>查询改写、混合融合、重排、纠错检索、多跳和分层诊断</td></tr><tr><td>紧邻</td><td>上下文工程、引用与溯源、中间迷失、Agent 循环</td></tr><tr><td>工程延伸</td><td>知识图谱、评测、可观测性、权限过滤和数据治理</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>记录基础 RAG 失败</li><li>定位查询/召回/排序/生成层</li><li>只为目标失败增加组件</li><li>每步保存证据与来源</li><li>限制多跳并处理冲突</li><li>消融验证端到端收益</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>答案错先做什么？</li><li>HyDE 做什么？</li><li>混合召回为何有用？</li><li>多跳主要风险？</li><li>如何证明组件有用？</li><li>假设“高级 RAG：让检索成为可诊断、可迭代的证据流程”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“高级 RAG：让检索成为可诊断、可迭代的证据流程”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>定位失败层并查看中间证据。</li><li>生成假设文档作为检索表示。</li><li>稠密语义与稀疏精确匹配互补。</li><li>早期错误滚雪球和循环。</li><li>固定集消融并看证据、答案、延迟成本。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2312.10997\" target=\"_blank\" rel=\"noopener\">Retrieval-Augmented Generation for Large Language Models: A Survey</a>：RAG 技术谱系</li><li><a href=\"https://arxiv.org/abs/2212.10496\" target=\"_blank\" rel=\"noopener\">Precise Zero-Shot Dense Retrieval without Relevance Labels (HyDE)</a>：假设文档检索</li><li><a href=\"https://arxiv.org/abs/2401.15884\" target=\"_blank\" rel=\"noopener\">Corrective Retrieval Augmented Generation</a>：检索质量判断与纠错</li><li><a href=\"https://dl.acm.org/doi/10.1145/1571941.1572114\" target=\"_blank\" rel=\"noopener\">Reciprocal Rank Fusion outperforms Condorcet and individual Rank Learning Methods</a>：RRF 排名融合</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
